export function taskKey(frameId, x, y, z) {
    return `${frameId}:${x}:${y}:${z}`;
}
/**
 * Priority-ordered queue of tile-fetch tasks with deduplication and
 * in-flight tracking. Owns `queue` (sorted by priority descending),
 * `queuedKeys` (dedup set), and `inFlight` (abort-aware task registry).
 * The external prefetcher wires the actual execution; this class
 * handles insertion, pruning, and lifecycle.
 */
export class TaskQueue {
    queue = [];
    queuedKeys = new Set();
    inFlight = new Map();
    get activeCount() {
        return this.inFlight.size;
    }
    get pendingCount() {
        return this.queue.length;
    }
    enqueue(tasks) {
        this.queue.push(...tasks);
        this.queue.sort((a, b) => b.priority - a.priority);
    }
    dequeue() {
        return this.queue.shift();
    }
    /**
     * Drop queued tasks for frames no longer in the schedule window and
     * tasks whose tiles are already cached.
     */
    prune(scheduledIds, tileCache) {
        const nextQueue = [];
        const nextKeys = new Set();
        for (const task of this.queue) {
            if (!scheduledIds.has(task.frameId))
                continue;
            if (tileCache.peek(task.frameId, task.x, task.y, task.z))
                continue;
            const key = taskKey(task.frameId, task.x, task.y, task.z);
            if (nextKeys.has(key))
                continue;
            nextQueue.push(task);
            nextKeys.add(key);
        }
        this.queue = nextQueue;
        this.queuedKeys = nextKeys;
    }
    /** Abort in-flight tasks whose frame is no longer in the schedule window. */
    abortStale(scheduledIds) {
        const toAbort = [];
        for (const [key, entry] of this.inFlight) {
            if (!scheduledIds.has(entry.frameId)) {
                entry.controller.abort();
                toAbort.push(key);
            }
        }
        for (const key of toAbort) {
            this.inFlight.delete(key);
        }
    }
    start(key, controller, frameId) {
        this.inFlight.set(key, { controller, frameId });
    }
    finish(key) {
        this.inFlight.delete(key);
    }
    isTracked(key) {
        return this.queuedKeys.has(key) || this.inFlight.has(key);
    }
    markQueued(key) {
        this.queuedKeys.add(key);
    }
    unmarkQueued(key) {
        this.queuedKeys.delete(key);
    }
    abortAll() {
        for (const [, entry] of this.inFlight) {
            entry.controller.abort();
        }
        this.inFlight.clear();
        this.queue.length = 0;
        this.queuedKeys.clear();
    }
    getInFlightKeys() {
        return [...this.inFlight.keys()];
    }
}
