  fill: white !important;
}
.deck-widget-scale line {
  stroke: white !important;
} */

.deck-widget-timeline .deck-widget-button-group {
  backdrop-filter: blur(12px);
  padding: 0.2em;
}

.deck-widget-range__track {
  background: #00000057;
}

/* Welcome widget */
.message-widget-root {
  position: relative;
  pointer-events: all;
  display: inline-block;
}

.message-widget-card {
  position: relative;
  background: rgba(14, 16, 25, 0.63);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 8px;
  backdrop-filter: blur(6px);
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.5);
}

.message-widget-card-collapsed {
  padding: 5px 8px;
}

.message-widget-card-expanded {
  padding: 10px 14px 8px;
  min-width: 220px;
  max-width: 360px;
  max-height: 400px;
  overflow-y: auto;
}

.message-widget-toggle {
  display: flex;
  align-items: center;
  gap: 5px;
  background: none;
  border: none;
  color: inherit;
  cursor: pointer;
  padding: 0;
  font-size: 11px;
  font-weight: 600;
  line-height: 1;
  font-family: inherit;
}

.message-widget-toggle-collapsed {
  color: #aaa;
}

.message-widget-toggle-expanded {
  position: absolute;
  bottom: 4px;
  right: 6px;
  font-size: 10px;
  padding: 2px 0;
}

.message-widget-toggle:hover {
  color: var(--button-icon-hover, rgb(24, 24, 26));
}

.message-widget-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 6px;
}

.message-widget-header-main {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

.message-widget-image {
  width: 18px;
  height: 18px;
  object-fit: contain;
  flex: 0 0 auto;
}

.message-widget-icon {
  flex: 0 0 auto;
}

.message-widget-label,
.message-widget-title {
  font-weight: 600;
  font-size: 14px;
}

.message-widget-content {
  color: var(--menu-text, rgb(24, 24, 26));
  font-size: 13px;
  line-height: 1.5;
}

.message-widget-content h2 {
  margin: 0 0 8px;
  font-size: 15px;
  font-weight: 600;
}

.message-widget-content p {
  margin: 0 0 6px;
}

.message-widget-content ul,
.message-widget-content ol {
  margin: 0 0 6px;
  padding-left: 18px;
}

.message-widget-chevron {
  font-size: 12px;
}

/* Street View widget */
.street-view-widget-root {
  position: relative;
  pointer-events: all;
  display: inline-block;
}

.street-view-widget-card {
  position: relative;
  background: rgba(14, 16, 25, 0.63);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 8px;
  backdrop-filter: blur(6px);
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.5);
}

.street-view-widget-card-collapsed {
  padding: 5px 8px;
}

.street-view-widget-card-expanded {
  padding: 10px 14px 10px;
  min-width: 260px;
  width: 320px;
}

.street-view-widget-toggle {
  display: flex;
  align-items: center;
  gap: 5px;
  background: none;
  border: none;
  color: inherit;
  cursor: pointer;
  padding: 0;
  font-size: 11px;
  font-weight: 600;
  line-height: 1;
  font-family: inherit;
}

.street-view-widget-toggle-collapsed {
  color: #aaa;
}

.street-view-widget-toggle-expanded {
  position: absolute;
  top: 0;
  right: 0;
  font-size: 10px;
  padding: 2px 0;
}

.street-view-widget-toggle:hover {
  color: var(--button-icon-hover, rgb(24, 24, 26));
}

.street-view-widget-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 6px;
}

.street-view-widget-header-main {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

.street-view-widget-label,
.street-view-widget-title {
  font-weight: 600;
  font-size: 14px;
}

.street-view-widget-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 8px;
  font-size: 12px;
}

.street-view-widget-key {
  color: var(--menu-text, rgb(24, 24, 26));
  opacity: 0.8;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.street-view-widget-link {
  color: var(--primary-text-link, #5794f2);
  text-decoration: none;
  white-space: nowrap;
}

.street-view-widget-link:hover {
  text-decoration: underline;
}

.street-view-widget-empty {
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  font-size: 13px;
  line-height: 1.4;
  color: var(--menu-text, rgb(24, 24, 26));
  opacity: 0.75;
  border: 1px solid rgba(127, 127, 127, 0.25);
  border-radius: 8px;
  background: rgba(0, 0, 0, 0.04);
  padding: 10px;
}

.street-view-widget-panorama {
  width: 100%;
  position: relative;
  overflow: hidden;
  border-radius: 8px;
  border: 1px solid rgba(127, 127, 127, 0.25);
  background: rgba(0, 0, 0, 0.08);
}

.street-view-widget-marker {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 18px;
  height: 18px;
  margin-left: -9px;
  margin-top: -9px;
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: none;
  z-index: 2;
}

.street-view-widget-marker::before {
  content: '';
  position: absolute;
  inset: 0;
  border: 2px solid rgba(255, 255, 255, 0.9);
  border-radius: 999px;
  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.35);
}

.street-view-widget-marker-dot {
  width: 6px;
  height: 6px;
  border-radius: 999px;
  background: #3388ff;
  box-shadow: 0 0 0 2px rgba(0, 0, 0, 0.35);
}

.street-view-widget-chevron {
  font-size: 12px;
}
